const sb = supabase.createClient(SUPABASE_URL, SUPABASE_KEY, { auth: { storageKey: AUTH_STORAGE_KEY, persistSession: true } });
const state = { user: null, profile: null, isAdmin: false, teachers: [], teacherProfiles: [], notes: [], studentAccounts: [], students: [], assignments: [], classes: [], classStudents: [], classTeachers: [], classCredits: [], classBalances: [], sessions: [], reports: [], reportLines: [], payDays: [], classRates: [], paymentAdjustments: [], tasks: [] };
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '—').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const badge = value => `<span class="badge ${esc(value).replaceAll(' ','-')}">${esc(value)}</span>`;
const title = (name, sub, action='') => `<div class="page-head"><div><h1>${name}</h1><p>${sub}</p></div>${action}</div>`;
const table = (heads, rows, empty='No records yet.') => `<table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows || `<tr><td colspan="${heads.length}">${empty}</td></tr>`}</tbody></table>`;
const teacherName = id => state.teachers.find(t=>t.id===id)?.full_name || state.teachers.find(t=>t.id===id)?.email || 'Unassigned';
const studentName = id => state.students.find(s=>s.id===id)?.full_name || 'Student';
const className = id => state.classes.find(item=>item.id===id)?.name || 'Legacy class';
const classTypes = value => (Array.isArray(value) ? value : [value]).filter(Boolean);

async function query(name, select='*', configure=q=>q) { const {data,error}=await configure(sb.from(name).select(select)); if(error) throw error; return data||[]; }
async function loadData() {
  const result = await loadAcademicData(sb, { isAdmin: state.isAdmin, week: getWeekRange() });
  Object.assign(state, result.data);
  state.dataErrors = result.errors;
  if (state.isAdmin) {
    [state.teachers,state.studentAccounts] = await Promise.all([
      query('profiles','id,email,full_name,tier,is_admin,created_at',q=>q.eq('tier','teacher')),
      query('profiles','id,email,full_name,tier,is_admin,created_at',q=>q.eq('tier','student').order('created_at',{ascending:false}))
    ]);
    state.teachers=state.teachers.map(account=>({...account,teacherProfile:state.teacherProfiles.find(profile=>profile.user_id===account.id)||null}));
  }
  else state.teachers = [{id:state.user.id,email:state.user.email,full_name:state.profile.full_name}];
}

function nav() {
  const admin=[['','Overview'],['directory','Teachers'],['students','Students'],['classes','Classes'],['schedule','Schedule'],['reports','Pay Reports'],['payments','Payments'],['tasks','Tasks']];
  const teacher=[['','My Overview'],['students','My Students'],['classes','My Classes'],['schedule','My Schedule'],['reports','Pay Day Report'],['tasks','My Tasks']];
  const page=location.pathname.replace(/^\/teachers\/?/,'').split('/')[0];
  $('#nav').innerHTML=(state.isAdmin?admin:teacher).map(([path,label])=>`<a class="nav-link ${page===path?'active':''}" href="/teachers/${path}">${label}</a>`).join('');
}

function overview() {
  const week=getWeekRange(), ownReport=state.reports.find(r=>r.teacher_user_id===state.user.id&&r.week_start===week.start);
  if(!state.isAdmin){
    const pending=state.tasks.filter(t=>t.status!=='Completed').length,day=activePayDay();
    return title('My Overview','Your students, schedule and pay day reporting at a glance.')+
      `<section class="report-cta"><h2>${day?'Pay day '+esc(day.pay_date):'Pay day reporting'}</h2><p>${day?'Enter the hours taught for each assigned class.':'Your administrator has not opened a pay day yet.'}</p>${day?(ownReport?.status==='Submitted'?badge('Submitted'):`<button class="ep-btn-primary" data-action="report">Report hours</button>`):''}${ownReport?.status==='Needs Changes'?`<p><strong>Changes requested:</strong> ${esc(ownReport.admin_comments)}</p>`:''}</section>`+
      stats([['Assigned students',state.students.length],['Classes this week',state.sessions.length],['Pending tasks',pending],['Report status',ownReport?.status||'Not started']]);
  }
  const activeTeachers=state.teachers.length, activeStudents=state.students.filter(s=>s.status==='Active').length;
  const pendingReports=state.reports.filter(r=>r.status==='Submitted').length, changes=state.reports.filter(r=>r.status==='Needs Changes').length;
  const submitted=new Set(state.reports.filter(r=>r.week_start===week.start&&r.status!=='Draft').map(r=>r.teacher_user_id));
  return title('Academic Overview','Administration for the current teaching week.','<button class="ep-btn-primary" data-register-payment>Register Payment</button>')+stats([
    ['Active teachers',activeTeachers],['Active students',activeStudents],['Classes scheduled',state.sessions.filter(s=>s.status==='Scheduled').length],['Reports pending',pendingReports],['Need corrections',changes],['Reports missing',Math.max(0,activeTeachers-submitted.size)],['Pending tasks',state.tasks.filter(t=>t.status!=='Completed').length],['No-shows',state.sessions.filter(s=>s.status==='No-show').length]
  ])+`<div class="quick"><button class="ep-btn-primary" data-action="class">Add Class</button><button class="btn" data-action="student">Add Student</button><button class="btn" data-action="assign">Assign Student</button><a class="btn link" href="/teachers/reports">View Weekly Reports</a><button class="btn" data-action="task">Create Task</button></div>`;
}
function stats(items){return `<div class="grid">${items.map(([label,value])=>`<article class="ep-card stat"><strong>${esc(value)}</strong><span>${label}</span></article>`).join('')}</div>`}

function teacherMetrics(teacher){
  const id=teacher.id, week=getWeekRange(), classLinks=activeTeacherClasses(id,state.classes,state.classTeachers), studentIds=uniqueTeacherStudentIds(id,state.assignments,state.classes,state.classTeachers,state.classStudents), hours=weeklyTeacherHours(id,state.sessions), report=currentTeacherReport(id,state.reports,week.start), pending=state.tasks.filter(task=>task.assigned_teacher_user_id===id&&task.status!=='Completed').length;
  return {classLinks,studentIds,hours,report,pending,status:profileStatus(teacher.teacherProfile),roles:teacherRoleCounts(id,state.classes,state.classTeachers)};
}

function roleSummary(roles){return Object.entries(roles).map(([role,count])=>`${count} ${role.replace(' teacher','')}`).join('<br>')||'—'}

function directory(){
  const metrics=state.teachers.map(teacher=>[teacher,teacherMetrics(teacher)]), missing=metrics.filter(([,m])=>!m.report).length;
  return title('Teachers','Operational directory for Teacher-tier accounts.')+
    stats([['Total accounts',state.teachers.length],['Active',metrics.filter(([,m])=>m.status==='Active').length],['Paused',metrics.filter(([,m])=>m.status==='Paused').length],['Inactive',metrics.filter(([,m])=>m.status==='Inactive').length],['Profiles incomplete',metrics.filter(([,m])=>m.status==='Profile incomplete').length],['Weekly reports missing',missing]])+
    `<div class="filters teacher-filters"><input id="teacherSearch" aria-label="Search teachers" placeholder="Search name or email"><select id="teacherStatus"><option value="">All operational statuses</option>${['Active','Paused','Inactive','Profile incomplete'].map(x=>`<option>${x}</option>`).join('')}</select><select id="teacherReport"><option value="">All report statuses</option>${['Missing','Not started','Draft','Submitted','Needs Changes','Approved','Paid'].map(x=>`<option>${x}</option>`).join('')}</select><select id="teacherTasks"><option value="">All task states</option><option value="pending">Has pending tasks</option><option value="clear">No pending tasks</option></select><button class="btn" id="clearTeacherFilters">Clear filters</button></div>`+
    `<div class="table-scroll">${table(['Teacher','Email','Operational status','Assigned students','Active classes','Role in classes','Taught hours this week','Billable hours this week','Weekly report','Pending tasks','Actions'],metrics.map(([teacher,m])=>`<tr data-teacher-row data-search="${esc(`${teacher.full_name||''} ${teacher.email||''}`.toLowerCase())}" data-status="${esc(m.status)}" data-report="${esc(m.report?.status||'Missing')}" data-pending="${m.pending?'pending':'clear'}"><td><strong>${esc(teacher.full_name||'Teacher')}</strong></td><td>${esc(teacher.email)}</td><td>${badge(m.status)}</td><td>${m.studentIds.size}</td><td>${m.classLinks.length}</td><td>${roleSummary(m.roles)}</td><td>${(m.hours.taughtMinutes/60).toFixed(1)}h</td><td>${(m.hours.billableMinutes/60).toFixed(1)}h</td><td>${badge(m.report?.status||'Missing')}</td><td>${m.pending}</td><td><div class="row-actions"><a class="btn compact link" href="/teachers/directory/${teacher.id}">Open profile</a>${teacher.teacherProfile?`<button class="btn compact" data-edit-teacher="${teacher.id}">Edit profile</button>`:`<button class="btn compact" data-init-teacher="${teacher.id}">Initialize profile</button>`}${m.report?`<a class="btn compact link" href="/teachers/directory/${teacher.id}?tab=reports">View report</a>`:''}<button class="btn compact" data-task-teacher="${teacher.id}">Create task</button></div></td></tr>`).join(''),'No teachers match these filters.') }</div>`;
}
function students(){return title(state.isAdmin?'Students':'My Students','Student records and active teacher assignments.',state.isAdmin?'<button class="ep-btn-primary" data-action="student">Add Student</button>':'')+
  (state.isAdmin?`<aside class="match-help"><strong>Account matching</strong><span>Use <b>Match account</b> to merge a manual student record with a newly registered English Peak Student account.</span></aside>`:'')+
  `<div class="filters"><input id="studentSearch" placeholder="Search name or email"><select id="statusFilter"><option value="">All statuses</option>${['Active','Paused','Inactive','Prospect'].map(x=>`<option>${x}</option>`)}</select></div>`+
  table(['Student','Email','Account','Level','Currency','Status','Teacher','Actions'],state.students.map(s=>{const a=state.assignments.find(a=>a.student_id===s.id&&a.status==='Active');return `<tr data-student-row data-search="${esc((s.full_name+' '+(s.email||'')).toLowerCase())}" data-status="${s.status}"><td>${esc(s.full_name)}</td><td>${esc(s.email)}</td><td>${s.account_matched_at?badge('Matched'):s.user_id?badge('Registered'):state.isAdmin?`<button class="btn compact" data-match="${s.id}">Match account</button>`:badge('Manual record')}</td><td>${esc(s.level)}</td><td>${badge(s.payment_currency||'MXN')}</td><td>${badge(s.status)}</td><td>${esc(teacherName(a?.teacher_user_id))}</td><td><div class="row-actions"><a class="btn compact link" href="/teachers/students/${s.id}">Open</a><button class="btn compact" data-edit-student="${s.id}">Edit</button></div></td></tr>`}).join(''),'No students assigned yet.')}

function studentDetail(id){const s=state.students.find(x=>x.id===id);if(!s)return title('Student unavailable','The record does not exist or you are not authorized to access it.');const a=state.assignments.find(x=>x.student_id===id&&x.status==='Active');return title(esc(s.full_name),`${esc(s.level)} · ${esc(s.status)}`,`<div class="quick"><button class="btn" data-edit-student="${s.id}">Edit Student</button>${state.isAdmin?'<button class="btn" data-action="assign">Reassign</button>':''}</div>`)+`<div class="tabs"><span>Overview</span><span>Schedule & Classes</span><span>Tasks</span><span>Notes</span><span>History</span></div><div class="grid"><article class="ep-card card"><h3>Basic information</h3><p>${esc(s.email)}<br>${esc(s.phone)}<br>${esc(s.company)}<br>${esc(s.timezone)}${s.start_date?`<br>Started ${esc(s.start_date)}`:''}<br><strong>Payment currency:</strong> ${esc(s.payment_currency||'MXN')}</p></article><article class="ep-card card"><h3>Current teacher</h3><p>${esc(teacherName(a?.teacher_user_id))}</p><p>${esc(s.classes_per_week)} classes/week</p></article></div>`+table(['Date','Time','Status','Notes'],state.sessions.filter(x=>x.student_id===id).map(x=>`<tr><td>${x.class_date}</td><td>${x.start_time}</td><td>${badge(x.status)}</td><td>${esc(x.notes)}</td></tr>`).join(''))}

function classes(){
  const visible=state.isAdmin?state.classes:state.classes.filter(item=>state.classTeachers.some(link=>link.class_id===item.id&&link.teacher_user_id===state.user.id&&link.status==='Active'));
  const sortableHead=(key,label)=>`<button class="class-sort" data-class-sort="${key}" aria-label="Sort by ${label}" aria-sort="none">${label}<span aria-hidden="true">↕</span></button>`;
  const teacherFilter=state.isAdmin?`<span class="class-tools-label">Teachers</span><select id="classTeacherFilterMode" aria-label="Teacher filter mode"><option value="include">Filter in</option><option value="exclude">Filter out</option></select><details class="teacher-picker"><summary><span data-teacher-filter-label>All teachers</span><span aria-hidden="true">⌄</span></summary><div class="teacher-picker-menu">${state.teachers.map(teacher=>`<label><input type="checkbox" value="${teacher.id}" data-class-teacher-filter> ${esc(teacher.full_name||teacher.email)}</label>`).join('')}</div></details><button class="btn compact hidden" id="clearClassTeacherFilter">Clear</button>`:'';
  return title(state.isAdmin?'Classes':'My Classes','Students may join multiple classes, and every class can have a teaching team.',state.isAdmin?'<button class="ep-btn-primary" data-action="class">Add Class</button>':'')+
    `<div class="class-tools" aria-label="Class list tools"><label class="class-search" for="classSearch"><span class="class-tools-label">Search classes</span><input id="classSearch" type="search" placeholder="Search class, student, or teacher" autocomplete="off"></label>${teacherFilter}<span class="class-result-count" id="classResultCount" aria-live="polite"></span></div><div class="table-scroll class-table"><table><thead><tr><th>${sortableHead('class','Class')}</th><th>${sortableHead('type','Type')}</th><th>Weekly</th>${state.isAdmin?'<th>Remaining</th>':''}<th>Students</th><th>${sortableHead('teacher','Main teacher')}</th><th>Secondary teachers</th><th>${sortableHead('status','Status')}</th><th>Actions</th></tr></thead><tbody>${visible.map(item=>{
      const links=state.classTeachers.filter(link=>link.class_id===item.id&&link.status==='Active');
      const students=state.classStudents.filter(link=>link.class_id===item.id&&link.status==='Active').map(link=>studentName(link.student_id));
      const main=links.find(link=>link.role==='Main teacher');
      const secondary=links.filter(link=>link.role==='Secondary teacher').map(link=>teacherName(link.teacher_user_id));
      const types=classTypes(item.class_type),mainName=teacherName(main?.teacher_user_id);
      const searchText=[item.name,...types,...students,mainName,...secondary,item.status].join(' ');
      return `<tr data-class-row data-search="${esc(searchText)}" data-teachers="${esc(links.map(link=>link.teacher_user_id).join(','))}" data-class="${esc(item.name)}" data-type="${esc(types.join(', '))}" data-teacher="${esc(mainName)}" data-status="${esc(item.status)}"><td><strong>${esc(item.name)}</strong></td><td><div class="type-list">${types.map(type=>badge(type)).join('')}</div></td><td>${item.classes_per_week}</td>${state.isAdmin?`<td><strong class="credit-count ${(state.classBalances.find(balance=>balance.class_id===item.id)?.classes_remaining??0)<=2?'credit-low':''}">${state.classBalances.find(balance=>balance.class_id===item.id)?.classes_remaining??0}</strong></td>`:''}<td>${esc(students.join(', ')||'No students')}</td><td>${esc(mainName)}</td><td>${esc(secondary.join(', ')||'—')}</td><td>${badge(item.status)}</td><td><div class="row-actions"><button class="btn compact" data-edit-class="${item.id}">Edit details</button>${state.isAdmin?`<button class="btn compact" data-class-payment="${item.id}">Register payment</button><button class="btn compact" data-add-credits="${item.id}">Add classes</button>`:''}</div></td></tr>`;
    }).join('')||`<tr data-class-empty><td colspan="${state.isAdmin?9:8}">No classes have been added yet.</td></tr>`}</tbody></table><p class="class-filter-empty hidden" data-class-filter-empty>No classes match your search or filters.</p></div>`;
}

function schedule(){return title(state.isAdmin?'Schedule':'My Schedule','Sessions for the current Monday–Sunday week.')+table(['Date','Time','Class','Student','Teacher','Duration','Status','Payable','Notes'],state.sessions.map(s=>`<tr><td>${s.class_date}</td><td>${s.start_time}–${s.end_time}</td><td>${esc(className(s.class_id))}</td><td>${esc(studentName(s.student_id))}</td><td>${esc(teacherName(s.teacher_user_id))}</td><td>${s.duration_minutes} min</td><td>${badge(s.status)}</td><td>${s.is_billable===true||['Completed','Make-up class'].includes(s.status)||s.billing_status==='Billable no-show'?'Yes':'No'}</td><td>${esc(s.notes)}</td></tr>`).join(''))}

function activePayDay(){return state.payDays.find(day=>day.status==='Open')}
function reportLines(reportId){return state.reportLines.filter(line=>line.report_id===reportId)}
function reportDetails(report){const lines=reportLines(report.id);return `<details><summary>${lines.length} reported item${lines.length===1?'':'s'}</summary><ul class="line-list">${lines.map(line=>`<li><strong>${esc(line.is_extra?'Extra hours':className(line.class_id))}</strong> · ${Number(line.hours).toFixed(2)}h${line.comment?` — ${esc(line.comment)}`:''}</li>`).join('')}</ul></details>`}
function reports(){
  const day=activePayDay();
  if(!state.isAdmin) return title('My Pay Day Reports',day?`The next pay day is ${day.pay_date}. Report every assigned class, including zero hours.`:'There is no open pay day yet.',day?'<button class="ep-btn-primary" data-action="report">Report hours</button>':'')+
    table(['Pay day','Hours','Reported details','Status'],state.reports.map(r=>`<tr><td>${esc(state.payDays.find(d=>d.id===r.pay_day_id)?.pay_date||r.week_end)}</td><td>${(reportLines(r.id).reduce((n,l)=>n+Number(l.hours),0)).toFixed(2)}h</td><td>${reportDetails(r)}</td><td>${badge(r.status)}</td></tr>`).join(''),'Your submitted pay day reports will appear here.');
  return title('Teacher Pay Reports','Review every submitted hour and the private payment totals.')+`<div class="table-scroll">${table(['Pay day','Teacher','Hours & details','Charged','Teacher pay','School share','Status','Actions'],state.reports.map(r=>{const lines=reportLines(r.id),profile=state.teacherProfiles.find(p=>p.user_id===r.teacher_user_id),adjustment=state.paymentAdjustments.find(a=>a.report_id===r.id),totals=paymentTotals(lines,state.classRates,profile?.hourly_rate,adjustment);return `<tr><td>${esc(state.payDays.find(d=>d.id===r.pay_day_id)?.pay_date||r.week_end)}</td><td><strong>${esc(teacherName(r.teacher_user_id))}</strong></td><td>${totals.hours.toFixed(2)}h${reportDetails(r)}</td><td>${money(totals.charged, OPERATING_CURRENCY)}</td><td><strong>${money(totals.teacherPay, OPERATING_CURRENCY)}</strong></td><td>${money(totals.schoolShare, OPERATING_CURRENCY)}</td><td>${badge(r.status)}</td><td><div class="row-actions"><button class="btn compact" data-adjust-payment="${r.id}">Adjust totals</button>${r.status==='Submitted'?`<button class="btn compact" data-approve="${r.id}">Approve</button><button class="btn compact" data-changes="${r.id}">Needs changes</button>`:''}</div></td></tr>`}).join(''),'No teachers have submitted hours yet.') }</div>`;
}
function payments(){
  const open=activePayDay(),payments=state.classCredits.filter(item=>item.transaction_type==='Payment');
  const receivedUsd=payments.filter(item=>item.payment_currency==='USD').reduce((sum,item)=>sum+Number(item.payment_amount||0),0);
  const receivedMxn=payments.reduce((sum,item)=>sum+Number(item.payment_currency==='USD'?item.payment_amount_mxn:item.payment_amount||0),0);
  const history=payments.map(item=>{const display=paymentDisplay(item);return `<tr><td>${esc(item.payment_date)}</td><td><strong>${item.student_id?esc(studentName(item.student_id)):'Payer not specified'}</strong><br><span class="rate-source">${esc(className(item.class_id))}</span></td><td><span class="currency-badge">${esc(item.payment_currency||'MXN')}</span></td><td><strong class="ledger-amount">${display.primary}</strong>${display.equivalent?`<br><span class="converted-amount">${display.equivalent} MXN</span>`:''}</td><td>${item.exchange_rate_usd_mxn?`<strong>${Number(item.exchange_rate_usd_mxn).toFixed(4)}</strong><br><span class="rate-source">Google Finance · captured ${esc((item.exchange_rate_fetched_at||'').slice(0,10))}</span>`:'—'}</td><td>${item.quantity}</td><td>${esc(item.note)}</td></tr>`}).join('');
  return title('Payments','A private ledger for student receipts, class balances, and teacher compensation.','<div class="quick"><button class="ep-btn-primary" data-register-payment>Register Payment</button><button class="btn" data-action="payday">Activate pay day</button></div>')+
    `<section class="payment-summary"><article class="ep-card money-stat"><span>MXN value received</span><strong><b>$</b>${money(receivedMxn,'MXN').replace(/^\$/,'')}</strong><small>Includes captured MXN equivalents</small></article><article class="ep-card money-stat"><span>USD received</span><strong><b>$</b>${money(receivedUsd,'USD').replace(/^\$/,'')}</strong><small>USD-paying students only</small></article><article class="ep-card money-stat"><span>Payments recorded</span><strong>${payments.length}</strong><small>Auditable receipts</small></article></section>`+
    (open?`<section class="ep-card pay-day-banner"><div><span class="eyebrow">Open pay day</span><h2>${esc(open.pay_date)}</h2><p>Reporting period: ${esc(open.period_start)} – ${esc(open.period_end)}</p></div><button class="btn" data-close-payday="${open.id}">Close reporting</button></section>`:'<div class="empty-state">No pay day is currently open. Activate one when teachers should report their hours.</div>')+
    `<section class="ledger-section"><div class="ledger-heading"><div><span class="eyebrow">Receivables ledger</span><h2 class="section-title">Student payment history</h2></div><p>USD receipts preserve the Google Finance rate used at registration.</p></div><div class="table-scroll payment-history">${table(['Date','Student / class','Currency','Amount','USD → MXN rate','Hours','Reference'],history,'No student payments have been registered yet.')}</div></section>`+
    `<section class="ledger-section rate-book"><div class="ledger-heading"><div><span class="eyebrow">Rate book</span><h2 class="section-title">Class payment rates</h2></div><p>Rates default to MXN. Teacher pay is automatic at 80% unless manually overridden.</p></div><div class="table-scroll payment-rates-table">${table(['Class','Charge per hour','Teacher per hour','Classes remaining','Actions'],state.classes.map(c=>{const rate=state.classRates.find(r=>r.class_id===c.id),currency=rateCurrency(rate?.currency_code),balance=state.classBalances.find(item=>item.class_id===c.id)?.classes_remaining??0,status=rateBalanceStatus(balance),teacherRate=rate?.teacher_rate??defaultTeacherRate(rate?.charge_rate);return `<tr><td><strong>${esc(c.name)}</strong><br><span class="currency-badge rate-currency-badge">${currency}</span></td><td><strong class="ledger-amount">${formatRateAmount(rate?.charge_rate,currency)}</strong></td><td><strong class="ledger-amount">${formatRateAmount(teacherRate,currency)}</strong><br><span class="rate-source">${rate?.teacher_rate==null?'Automatic · 80%':'Manual override'}</span></td><td><span class="balance-indicator ${status.key}" aria-label="${balance} classes remaining, ${status.label}" title="${status.label}"><strong>${balance}</strong></span></td><td><button class="btn compact rate-edit" data-rate="${c.id}">Edit rates</button></td></tr>`}).join(''),'Add a class before setting payment rates.')}</div></section>`;
}

function tasks(){return title(state.isAdmin?'Tasks':'My Tasks','Assignments and append-only comment history.',state.isAdmin?'<button class="ep-btn-primary" data-action="task">Create Task</button>':'')+table(['Task','Teacher','Student','Due','Status',''],state.tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong><br>${esc(t.description)}</td><td>${esc(teacherName(t.assigned_teacher_user_id))}</td><td>${esc(studentName(t.related_student_id))}</td><td>${esc(t.due_date)}</td><td><select data-task-status="${t.id}">${['Not Started','In Progress','Completed'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`)}</select></td><td><button class="btn" data-comment="${t.id}">Comments</button></td></tr>`).join(''),'No tasks assigned.')}

function detailTabs(active){return `<div class="tabs teacher-tabs" role="tablist">${[['overview','Overview'],['students','Students'],['classes','Classes & Schedule'],['reports','Weekly Reports'],['tasks','Tasks'],['notes','Admin Notes']].map(([key,label])=>`<button role="tab" aria-selected="${active===key}" class="${active===key?'active':''}" data-teacher-tab="${key}">${label}</button>`).join('')}</div>`}

function studentConnections(id,studentId,classLinks){
  const values=[]; if(state.assignments.some(a=>a.teacher_user_id===id&&a.student_id===studentId&&a.status==='Active'))values.push('Direct assignment');
  const classIds=new Set(classLinks.map(x=>x.class_id)); state.classStudents.filter(x=>x.student_id===studentId&&x.status==='Active'&&classIds.has(x.class_id)).forEach(x=>values.push(`Class: ${className(x.class_id)}`)); return values;
}

function teacherDetailPanel(tab,t,m,scoped){
  if(tab==='students') return `<div class="table-scroll">${table(['Student','Email','Level','Connection','Active classes with teacher','Next scheduled class','Status','Open student'],[...m.studentIds].map(id=>{const student=state.students.find(x=>x.id===id);if(!student)return '';const connections=studentConnections(t.id,id,m.classLinks),next=scoped.sessions.filter(x=>x.student_id===id&&`${x.class_date}T${x.start_time||'00:00'}`>=new Date().toISOString().slice(0,16)).sort((a,b)=>a.class_date.localeCompare(b.class_date))[0];return `<tr><td>${esc(student.full_name)}</td><td>${esc(student.email)}</td><td>${esc(student.level)}</td><td>${connections.map(esc).join('<br>')}</td><td>${connections.filter(x=>x.startsWith('Class:')).length}</td><td>${next?`${esc(next.class_date)} ${esc(next.start_time)}`:'—'}</td><td>${badge(student.status)}</td><td><a href="/teachers/students/${student.id}">Open student</a></td></tr>`}).join(''),'No students currently connected to this teacher.') }</div>`;
  if(tab==='classes') return `<h2 class="section-title">Active classes</h2><div class="table-scroll">${table(['Class name','Class type or types','Teacher role','Students','Weekly schedule','Status'],m.classLinks.map(link=>{const item=state.classes.find(x=>x.id===link.class_id);const count=state.classStudents.filter(x=>x.class_id===link.class_id&&x.status==='Active').length;return `<tr><td>${esc(item?.name)}</td><td>${classTypes(item?.class_type).map(badge).join(' ')}</td><td>${esc(link.role)}</td><td>${count}</td><td>${esc(item?.weekly_schedule||item?.schedule||'Not specified')}</td><td>${badge(item?.status)}</td></tr>`}).join(''),'No active classes assigned.') }</div><h2 class="section-title">Sessions this week</h2><div class="table-scroll">${table(['Date','Time','Class','Student','Status','Duration','Taught','Billable','Notes'],scoped.sessions.map(x=>`<tr><td>${esc(x.class_date)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(className(x.class_id))}</td><td>${esc(studentName(x.student_id))}</td><td>${badge(x.status)}</td><td>${x.duration_minutes||0} min</td><td>${['Completed','Make-up class'].includes(x.status)?'Yes':'No'}</td><td>${calculateReport([x]).totalBillableMinutes?'Yes':'No'}</td><td>${esc(x.notes)}</td></tr>`).join(''),'No sessions scheduled this week.') }</div>`;
  if(tab==='reports') return `<div class="table-scroll">${table(['Week','Completed hours','Billable hours','Completed classes','No-shows','Status','Submitted at','Approved at','Action'],scoped.reports.sort((a,b)=>String(b.week_start).localeCompare(String(a.week_start))).map(r=>`<tr><td>${esc(r.week_start)} – ${esc(r.week_end)}</td><td>${(Number(r.total_completed_minutes||0)/60).toFixed(1)}h</td><td>${(Number(r.total_billable_minutes||0)/60).toFixed(1)}h</td><td>${r.total_completed_classes||0}</td><td>${r.total_no_shows||0}</td><td>${badge(r.status)}</td><td>${esc(r.submitted_at)}</td><td>${esc(r.approved_at)}</td><td><div class="row-actions"><a href="/teachers/reports" class="btn compact link">Open</a>${r.status==='Submitted'?`<button class="btn compact" data-approve="${r.id}">Approve</button>`:''}${['Submitted','Approved'].includes(r.status)?`<button class="btn compact" data-changes="${r.id}">Request changes</button>`:''}${['Needs Changes','Paid'].includes(r.status)?'':r.status==='Draft'?`<button class="btn compact" data-reopen-report="${r.id}">Reopen</button>`:''}</div></td></tr>`).join(''),'No weekly reports submitted yet.') }</div>`;
  if(tab==='tasks') return `<div class="quick detail-action"><button class="ep-btn-primary" data-task-teacher="${t.id}">Create Task for this teacher</button></div><div class="table-scroll">${table(['Title','Related student','Due date','Status','Comments','Created by','Updated'],scoped.tasks.map(task=>`<tr><td><strong>${esc(task.title)}</strong></td><td>${esc(studentName(task.related_student_id))}</td><td>${esc(task.due_date)}</td><td><select data-task-status="${task.id}">${['Not Started','In Progress','Completed'].map(x=>`<option ${x===task.status?'selected':''}>${x}</option>`).join('')}</select></td><td><button class="btn compact" data-comment="${task.id}">Open comments</button></td><td>${esc(teacherName(task.assigned_by_user_id))}</td><td>${esc(task.updated_at)}</td></tr>`).join(''),'No tasks assigned.') }</div>`;
  if(tab==='notes') return `<article class="ep-card card admin-note"><strong>Visible only to administrators.</strong><form id="teacherNotesForm" data-id="${t.id}"><div class="field"><label>Private administrative notes</label><textarea name="internal_notes">${esc(t.teacherProfile?.internal_notes||'')}</textarea></div><button class="ep-btn-primary" ${t.teacherProfile?'':'disabled'}>Save note</button></form></article><h2 class="section-title">Administrator notes</h2>${scoped.notes.map(note=>`<article class="ep-card card"><p>${esc(note.note||note.content)}</p><small>${esc(note.created_at)}</small></article>`).join('')||'<p class="empty-state">No administrator notes.</p>'}`;
  const upcoming=scoped.sessions.filter(x=>`${x.class_date}T${x.start_time||'00:00'}`>=new Date().toISOString().slice(0,16)).slice(0,5), pending=scoped.tasks.filter(x=>x.status!=='Completed').slice(0,5);
  return `<div class="detail-grid"><article class="ep-card card"><h2>Operational profile</h2><dl><dt>Status</dt><dd>${badge(m.status)}</dd><dt>Timezone</dt><dd>${esc(t.teacherProfile?.timezone)}</dd><dt>Hourly rate</dt><dd>${t.teacherProfile?.hourly_rate==null?'—':`$${Number(t.teacherProfile.hourly_rate).toFixed(2)}`}</dd><dt>Updated</dt><dd>${esc(t.teacherProfile?.updated_at)}</dd></dl></article><article class="ep-card card"><h2>Current weekly report</h2><p>${badge(m.report?.status||'Missing')}</p><p>${m.report?`${(Number(m.report.total_billable_minutes||0)/60).toFixed(1)} billable hours`:'No report has been created for this week.'}</p></article><article class="ep-card card"><h2>Next upcoming classes</h2>${upcoming.map(x=>`<p><strong>${esc(x.class_date)} ${esc(x.start_time)}</strong><br>${esc(className(x.class_id))} · ${esc(studentName(x.student_id))}</p>`).join('')||'<p>No upcoming classes.</p>'}</article><article class="ep-card card"><h2>Latest pending tasks</h2>${pending.map(x=>`<p><strong>${esc(x.title)}</strong><br>Due ${esc(x.due_date)}</p>`).join('')||'<p>No pending tasks.</p>'}</article></div><article class="ep-card card"><h2>Recent admin activity</h2><p>${[t.teacherProfile?.updated_at,...scoped.tasks.map(x=>x.updated_at),...scoped.reports.map(x=>x.approved_at||x.submitted_at)].filter(Boolean).sort().reverse().slice(0,4).map(x=>new Date(x).toLocaleString()).join('<br>')||'No recent teacher activity.'}</p></article>`;
}

function teacherDetail(id){
  if(!canLoadTeacherDetail(state,id))return title('Access denied','Teacher operational profiles are administrative only.'); const t=state.teachers.find(x=>x.id===id);if(!t)return title('Teacher not found','This Teacher account is unavailable.');
  const m=teacherMetrics(t),scoped=teacherScopedData(id,state),tab=new URLSearchParams(location.search).get('tab')||'overview', future=scoped.sessions.some(x=>x.class_date>new Date().toISOString().slice(0,10));
  return title(esc(t.full_name||'Teacher'),`${esc(t.email)} · ${esc(t.teacherProfile?.timezone||'Timezone not set')}`,`<div class="quick">${t.teacherProfile?`<button class="btn" data-edit-teacher="${id}">Edit Profile</button>`:''}<button class="ep-btn-primary" data-task-teacher="${id}">Create Task</button></div>`)+
    `<div class="teacher-meta">${badge(m.status)}<span>Teacher since ${esc((t.teacherProfile?.created_at||t.created_at||'').slice(0,10))}</span></div>`+
    (!t.teacherProfile?`<article class="ep-card incomplete-card"><h2>Operational profile incomplete</h2><p>Initialize this profile before managing operational status, rate, or private notes.</p><button class="ep-btn-primary" data-init-teacher="${id}">Initialize Teacher Profile</button></article>`:'')+
    (m.status==='Inactive'&&(m.studentIds.size||m.classLinks.length||future)?`<aside class="warning-card"><strong>Inactive teacher still has operational connections.</strong> ${m.studentIds.size} active students, ${m.classLinks.length} active classes${future?', and future sessions':''}. Nothing has been reassigned automatically.</aside>`:'')+
    stats([['Unique assigned students',m.studentIds.size],['Active classes',m.classLinks.length],['Classes this week',scoped.sessions.length],['Taught hours',(m.hours.taughtMinutes/60).toFixed(1)],['Billable hours',(m.hours.billableMinutes/60).toFixed(1)],['Pending tasks',m.pending],['Current report',m.report?.status||'Missing']])+detailTabs(tab)+`<section role="tabpanel">${teacherDetailPanel(tab,t,m,scoped)}</section>`;
}
function render(){nav();const parts=location.pathname.replace(/^\/teachers\/?/,'').split('/').filter(Boolean);const page=parts[0]||'';$('#view').innerHTML=page==='directory'?(parts[1]?teacherDetail(parts[1]):directory()):page==='students'?(parts[1]?studentDetail(parts[1]):students()):page==='classes'?classes():page==='schedule'?schedule():page==='reports'?reports():page==='payments'&&state.isAdmin?payments():page==='tasks'?tasks():overview();bind()}

function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');bindModalControls()} function closeModal(){$('#modal').classList.add('hidden')}
function formField(label,name,type='text',extra=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" ${extra}></div>`}
function stepperField(label,name,value,min=0,required=''){return `<div class="field"><label>${label}</label><div class="number-stepper"><div class="stepper-buttons"><button type="button" data-step="1" aria-label="Increase ${label}">▲</button><button type="button" data-step="-1" aria-label="Decrease ${label}">▼</button></div><input name="${name}" type="number" value="${esc(value)}" min="${min}" ${required}></div></div>`}
function optionalStartDate(value=''){const enabled=Boolean(value);return `<div class="optional-field"><div class="optional-field-head"><span>Start date</span><label class="switch"><input type="checkbox" data-start-date-toggle ${enabled?'checked':''}><span class="switch-track" aria-hidden="true"></span><span data-toggle-label>${enabled?'On':'Off'}</span></label></div><div class="field start-date-field ${enabled?'':'hidden'}"><input name="start_date" type="date" value="${esc(value)}" ${enabled?'':'disabled'}></div></div>`}
function studentForm(){openModal(`<h2 class="ep-heading">Add Student</h2><form id="studentForm">${formField('Full name','full_name','text','required')}${formField('Email','email','email')}${formField('Level','level')}${optionalStartDate()}<div class="field"><label>Payment currency</label><select name="payment_currency"><option value="MXN">MXN · Mexican pesos</option><option value="USD">USD · US dollars</option></select></div><div class="field"><label>Status</label><select name="status">${['Active','Paused','Inactive','Prospect'].map(x=>`<option>${x}</option>`)}</select></div>${stepperField('Classes per week','classes_per_week','',0)}<button class="ep-btn-primary">Save Student</button></form>`)}
function studentEditForm(id){const s=state.students.find(x=>x.id===id);if(!s)return;openModal(`<h2 class="ep-heading">Edit Student</h2><p class="form-note">Update academic and contact details. Account matching remains an Admin-only action.</p><form id="studentEditForm" data-id="${id}">${formField('Full name','full_name','text',`required value="${esc(s.full_name)}"`)}${formField('Email','email','email',`value="${esc(s.email||'')}"`)}${formField('Phone','phone','tel',`value="${esc(s.phone||'')}"`)}${formField('Company','company','text',`value="${esc(s.company||'')}"`)}${formField('Level','level','text',`value="${esc(s.level||'')}"`)}${optionalStartDate(s.start_date)}${state.isAdmin?`<div class="field"><label>Payment currency</label><select name="payment_currency"><option value="MXN" ${(s.payment_currency||'MXN')==='MXN'?'selected':''}>MXN · Mexican pesos</option><option value="USD" ${s.payment_currency==='USD'?'selected':''}>USD · US dollars</option></select><p class="field-help">Used as the default whenever this student's payment is registered.</p></div>`:''}<div class="field"><label>Status</label><select name="status">${['Active','Paused','Inactive','Prospect'].map(x=>`<option ${x===s.status?'selected':''}>${x}</option>`)}</select></div>${stepperField('Classes per week','classes_per_week',s.classes_per_week??'',0)}${formField('Timezone','timezone','text',`required value="${esc(s.timezone||'America/Mexico_City')}"`)}<div class="field"><label>Academic notes</label><textarea name="academic_notes">${esc(s.academic_notes||'')}</textarea></div><button class="ep-btn-primary">Save Changes</button></form>`)}
function assignForm(){openModal(`<h2 class="ep-heading">Assign Student</h2><form id="assignForm"><div class="field"><label>Student</label><select name="student_id">${state.students.map(s=>`<option value="${s.id}">${esc(s.full_name)}</option>`)}</select></div><div class="field"><label>Teacher</label><select name="teacher_user_id">${state.teachers.map(t=>`<option value="${t.id}">${esc(t.full_name||t.email)}</option>`)}</select></div><button class="ep-btn-primary">Assign</button></form>`)}
function classForm(){openModal(`<h2 class="ep-heading">Add Class</h2><p class="form-note">Set up the class and its teaching team now. Students can be added now or later.</p><form id="classForm">${formField('Class name','name','text','required')}<fieldset><legend>Type of class</legend><p class="field-help">Select one or more types.</p><div class="check-list class-type-list">${['General English','Conversational','Business English','Test Prep','Other'].map(x=>`<label><input type="checkbox" name="class_types" value="${x}"> ${x}</label>`).join('')}</div></fieldset>${stepperField('Classes weekly','classes_per_week',1,1,'required')}<fieldset><legend>Students (optional)</legend><p class="field-help">Leave this empty if student information is not available yet. You can add students when you edit the class.</p><div class="roster-search"><label for="classStudentSearch">Search students</label><input id="classStudentSearch" type="search" placeholder="Search by student name" autocomplete="off"></div><div class="check-list" data-class-student-list>${state.students.map(s=>`<label data-class-student data-search="${esc(s.full_name.toLowerCase())}"><input type="checkbox" name="student_ids" value="${s.id}"> ${esc(s.full_name)}</label>`).join('')}</div><p class="roster-empty hidden" data-class-student-empty>No students match your search.</p></fieldset><div class="field"><label>Main teacher</label><select name="main_teacher_id" required><option value="">Select a teacher…</option>${state.teachers.map(t=>`<option value="${t.id}">${esc(t.full_name||t.email)}</option>`)}</select></div><fieldset><legend>Secondary teachers</legend><div class="check-list">${state.teachers.map(t=>`<label><input type="checkbox" name="secondary_teacher_ids" value="${t.id}"> ${esc(t.full_name||t.email)}</label>`).join('')}</div></fieldset><button class="ep-btn-primary">Add Class</button></form>`)}
function classEditForm(id){
  const item=state.classes.find(x=>x.id===id);if(!item)return;
  const selected=classTypes(item.class_type), activeStudents=new Set(state.classStudents.filter(link=>link.class_id===id&&link.status==='Active').map(link=>link.student_id)), links=state.classTeachers.filter(link=>link.class_id===id&&link.status==='Active'), main=links.find(link=>link.role==='Main teacher')?.teacher_user_id, secondary=new Set(links.filter(link=>link.role==='Secondary teacher').map(link=>link.teacher_user_id));
  const adminFields=state.isAdmin?`<fieldset><legend>Students</legend><div class="roster-search"><label for="classStudentSearch">Search students</label><input id="classStudentSearch" type="search" placeholder="Search by student name"></div><div class="check-list" data-class-student-list>${state.students.map(student=>`<label data-class-student data-search="${esc(student.full_name.toLowerCase())}"><input type="checkbox" name="student_ids" value="${student.id}" ${activeStudents.has(student.id)?'checked':''}> ${esc(student.full_name)}</label>`).join('')}</div><p class="roster-empty hidden" data-class-student-empty>No students match your search.</p></fieldset><div class="field"><label>Main teacher</label><select name="main_teacher_id" required>${state.teachers.map(teacher=>`<option value="${teacher.id}" ${teacher.id===main?'selected':''}>${esc(teacher.full_name||teacher.email)}</option>`).join('')}</select></div><fieldset><legend>Secondary teachers</legend><div class="check-list">${state.teachers.map(teacher=>`<label><input type="checkbox" name="secondary_teacher_ids" value="${teacher.id}" ${secondary.has(teacher.id)?'checked':''}> ${esc(teacher.full_name||teacher.email)}</label>`).join('')}</div></fieldset>`:'';
  openModal(`<h2 class="ep-heading">Edit Class</h2><p class="form-note">${state.isAdmin?'Update every class detail, roster, and teaching assignment. Reassigning preserves historical sessions.':'Update the academic details for this assigned class.'}</p><form id="classEditForm" data-id="${id}">${formField('Class name','name','text',`required value="${esc(item.name)}"`)}<fieldset><legend>Type of class</legend><div class="check-list class-type-list">${['General English','Conversational','Business English','Test Prep','Other'].map(x=>`<label><input type="checkbox" name="class_types" value="${x}" ${selected.includes(x)?'checked':''}> ${x}</label>`).join('')}</div></fieldset>${stepperField('Classes weekly','classes_per_week',item.classes_per_week,1,'required')}<div class="field"><label>Status</label><select name="status">${['Active','Paused','Ended'].map(x=>`<option ${x===item.status?'selected':''}>${x}</option>`).join('')}</select></div>${adminFields}<button class="ep-btn-primary">Save Changes</button></form>`)
}
function classCreditForm(id,type){const item=state.classes.find(x=>x.id===id),payment=type==='Payment',globalPayment=payment&&!item;const classOptions=state.classes.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');openModal(`<h2 class="ep-heading">${payment?'Register Payment':'Add classes'}${item?` · ${esc(item.name)}`:''}</h2><p class="form-note">${payment?'Enter the hours covered and the payment total will be calculated from the class rate. Both values remain editable, and the hours are added to the class balance.':'Master Admin adjustment: add hours without registering a payment. This creates an audit entry.'}</p><form id="classCreditForm" data-id="${id||''}" data-type="${type}">${globalPayment?`<div class="field"><label>Class</label><select name="class_id" data-payment-class required><option value="">Select a class</option>${classOptions}</select></div>`:''}${payment?`<div class="field"><label>Payer <span class="optional-label">Optional</span></label><select name="student_id"><option value="">${globalPayment?'Select a class first':'Not specified'}</option></select><p class="field-help">Leave this blank when the payer is unknown or does not need to be recorded.</p></div><div class="field"><label>Payment currency</label><select name="payment_currency" data-payment-currency><option value="MXN">MXN · Mexican pesos</option><option value="USD">USD · US dollars</option></select></div>`:''}${stepperField(payment?'Hours covered':'Hours to add','quantity',1,.25,'required step="0.25"')}${payment?formField('Money amount','payment_amount','number','required min="0.01" step="0.01"')+`<p class="field-help payment-calculation" data-payment-calculation>Select a class to calculate the total from its hourly rate. You can edit the amount if needed.</p>`+formField('Payment date','payment_date','date',`required value="${new Date().toISOString().slice(0,10)}"`)+`<div class="exchange-preview" data-exchange-preview aria-live="polite"></div><input type="hidden" name="exchange_rate_usd_mxn"><input type="hidden" name="payment_amount_mxn"><input type="hidden" name="exchange_rate_fetched_at"><input type="hidden" name="exchange_rate_source">`:''}<div class="field"><label>Note</label><textarea name="note" placeholder="Package, reason, or reference"></textarea></div><button class="ep-btn-primary">${payment?'Register Payment':'Add hours remaining'}</button></form>`)}
function payDayForm(){const friday=new Date();friday.setUTCDate(friday.getUTCDate()+((5-friday.getUTCDay()+7)%7));const date=friday.toISOString().slice(0,10),start=new Date(friday);start.setUTCDate(start.getUTCDate()-6);openModal(`<h2 class="ep-heading">Activate a Pay Day</h2><p class="form-note">Friday is suggested, but any date can be selected.</p><form id="payDayForm">${formField('Pay date','pay_date','date',`required value="${date}"`)}${formField('Period starts','period_start','date',`required value="${start.toISOString().slice(0,10)}"`)}${formField('Period ends','period_end','date',`required value="${date}"`)}<button class="ep-btn-primary">Open reporting</button></form>`)}
