  if(!selectedClassTypes.length)throw new Error('Select at least one type of class.');
  const result=await sb.rpc('ep_create_class_with_team',{p_name:data.name.trim(),p_class_types:selectedClassTypes,p_classes_per_week:Number(data.classes_per_week),p_student_ids:formData.getAll('student_ids'),p_main_teacher_id:data.main_teacher_id,p_secondary_teacher_ids:formData.getAll('secondary_teacher_ids')});
  if(result.error)throw result.error;
